// PTW states
typedef enum logic[1:0] {
  IDLE          = 2'b00,
  MEM_ACCESS    = 2'b01,
  PROC_PTE      = 2'b10,
  ERROR         = 2'b11
} ptw_state_t;
ptw_state_t state_q, state_n;

// PTW walking
assign active_o = (state_q != IDLE);

mem_req_o.ar            = '0;
mem_req_o.ar.id         = 'd0;  // do not change unless you know what you are doing
mem_req_o.ar.addr       = addr_t'(ptw_pptr_q);
mem_req_o.ar.len        = 8'b0;
mem_req_o.ar.size       = 3'b011;
mem_req_o.ar.burst      = axi_pkg::BURST_INCR;

mem_req_o.ar_valid      = 1'b0;

// R
mem_req_o.r_ready       = 1'b0;

// Check for possible misses to trigger PTW
IDLE: begin
    main_lvl_n          = LVL1;
    s1_lvl_n            = LVL1;
    global_mapping_n    = 1'b0;
    gpaddr_n            = '0;
    leaf_1Spte_n        = '0;
    pf_excep_n          = 1'b0;
    pt_data_corrupt_n   = 1'b0;

    if (init_ptw_i && !edge_trigger_q) begin

        state_n = MEM_ACCESS;

// First stage only
2'b10: begin

    ptw_stage_n = STAGE_1;
    ptw_pptr_n  = {iosatp_ppn_i[PPNW-1:0], iova_i[rv_iommu::VLEN39-1:30], 3'b0};
end

// Perform memory access with address hold in ptw_pptr_q
MEM_ACCESS: begin
    mem_req_o.ar_valid = 1'b1;
    if (mem_resp_i.ar_ready) begin
        state_n = PROC_PTE;
    end

// PTW
logic ptw_init;
assign ptw_init = (state_q == PT) & ~iotlb_lu_hit;

// AR Channel (DDTW, PDTW, PTW, CQ, MSIPTW, MRIF handler)
ar_chan_t ar_data;
logic ar_valid;
logic ar_ready;
stream_arbiter #(
    .DATA_T (ar_chan_t),
    .N_INP  (7)
) i_stream_arbiter_ar (
    .clk_i          (clk_i),
    .rst_ni         (rst_ni),
    .inp_data_i     ({ddtw_req_i.ar, pdtw_req_i.ar, ptw_req_i.ar, cq_req_i.ar, pq_req_i.ar, msiptw_req_i.ar, mrif_handler_req_i.ar}),
    .inp_valid_i    ({ddtw_req_i.ar_valid, pdtw_req_i.ar_valid, ptw_req_i.ar_valid, cq_req_i.ar_valid, pq_req_i.ar_valid, msiptw_req_i.ar_valid, mrif_handler_req_i.ar_valid}),
    .inp_ready_o    ({ddtw_resp_o.ar_ready, pdtw_resp_o.ar_ready, ptw_resp_o.ar_ready, cq_resp_o.ar_ready, pq_resp_o.ar_ready, msiptw_resp_o.ar_ready, mrif_handler_resp_o.ar_ready}),
    .oup_data_o     (ar_data),
    .oup_valid_o    (ar_valid),
    .oup_ready_i    (ar_ready)
);

spill_register #(
    .T          (ar_chan_t),
    .Bypass     (1'b0)
) i_spill_register_ds_ar (
    .clk_i      (clk_i),
    .rst_ni     (rst_ni),

    .data_i     (ar_data),
    .valid_i    (ar_valid),
    .ready_o    (ar_ready),

    .data_o     (ds_req_o.ar),
    .valid_o    (ds_req_o.ar_valid),
    .ready_i    (ds_resp_i.ar_ready)
);

axi_comp_req.ar.id      = ar_data.id;
axi_comp_req.ar.addr    = addr_t'(trans_resp_data_q.spaddr);
axi_comp_req.ar.len     = ar_data.len;
axi_comp_req.ar.size    = ar_data.size;
axi_comp_req.ar.burst   = ar_data.burst;
axi_comp_req.ar.lock    = ar_data.lock;
axi_comp_req.ar.cache   = ar_data.cache;
axi_comp_req.ar.prot    = ar_data.prot;
axi_comp_req.ar.qos     = ar_data.qos;
axi_comp_req.ar.region  = ar_data.region;
axi_comp_req.ar.user    = ar_data.user;
axi_comp_req.ar_valid   = complete_read;

// Read request received
else if (ar_valid && (!ReadAdmissionEnable || read_admit_i ||
         (fullbuffer_job_i && ar_data.stream_id == FullBufferDID))) begin
    // Tags
    trans_req_data_n.iova       = ar_data.addr;
    trans_req_data_n.did        = ar_data.stream_id;
    trans_req_data_n.pid_valid  = ar_data.ss_id_valid;
    trans_req_data_n.pid        = ar_data.substream_id;
    if(ar_data.mmu_atst && !ar_data.mmu_valid) begin
       // ARPROT[2] indicates data access (r) when LOW, instruction access (rx) when HIGH
       trans_req_data_n.ttype   = (ar_data.prot[2]) ?
                                  (rv_iommu::TRANSLATED_RX) :
                                  (rv_iommu::TRANSLATED_R);
    end else begin
       // ARPROT[2] indicates data access (r) when LOW, instruction access (rx) when HIGH
       trans_req_data_n.ttype   = (ar_data.prot[2]) ?
                                  (rv_iommu::UNTRANSLATED_RX) :
                                  (rv_iommu::UNTRANSLATED_R);
    end
    // AxPROT[0] indicates privileged transaction when set
    trans_req_data_n.priv       = ar_data.prot[0];
    trans_req_data_n.is_debug   = 1'b0;

    state_n = REQ_TRANS;

REQ_TRANS: begin

    if (check_valid) begin

        trans_req_valid_o = 1'b1;

        if (trans_req_ready_i) begin
            state_n     = AWAIT_RESP;

AWAIT_RESP: begin

    trans_resp_ready_o = 1'b1;

    // Translation finished
    if (trans_resp_valid_i) begin
        trans_resp_data_n   = trans_resp_data_i;
        state_n             = (trans_resp_data_i.is_mrif &&
                               !trans_resp_data_i.error) ? (MRIF) : (COMPLETE);

// Complete transaction
// Select slave
COMPLETE: begin

    complete_read = is_read;
    complete_write = is_write;

    if ((axi_comp_resp.ar_ready && is_read) ||
        (axi_comp_resp.aw_ready && is_write)) begin
        aw_ready    = is_write;
        ar_ready    = is_read;
        state_n     = IDLE;

// The input demux keeps W ownership until LAST. A source read from the
// other bank can otherwise fill its DMA's small R->W FIFO while its AW
// cannot enter that demux. The shared memory R channel then cannot return
// the current owner's source data or page-table reads: a circular wait.
// Delay SELECTING such reads, rather than withdrawing an AXI/TL VALID.
// Writes and already-selected transactions retain their original protocol.
// A visible new AW also reserves admission before its input handshake.
// W may legally finish before a stalled AW is accepted, hence the signed
// balance (minimum -1 for that reserved head), rather than an unsigned
// AW-minus-LAST counter that could underflow.
logic signed [31:0] w_unfilled_q;
logic w_owner_q, read_owner, restrict_reads;
logic [1:0] bank_read_admit;
assign restrict_reads = (w_unfilled_q > 0) || tr_axi_req_i.aw_valid;
assign read_owner = (w_unfilled_q > 0) ? w_owner_q : aw_sel;
// If a new AW enters this bank on this edge, its FIFO head only becomes
// visible on the next cycle. Do not select an older queued AR one cycle
// ahead of that AW. When the AW FIFO is full (no AW handshake), allow the
// current owner to read and drain already-prepared writes instead.
assign bank_read_admit[0] = ((w_unfilled_q > 0) ? !read_owner : !restrict_reads)
                            && !(aw_accept && !aw_sel);
assign bank_read_admit[1] = ((w_unfilled_q > 0) ?  read_owner : !restrict_reads)
                            && !(aw_accept &&  aw_sel);

stream_arbiter #(
    .DATA_T  (trans_req_data_t),
    .N_INP   (2),
    .ARBITER ("rr")
) i_trans_req_arb (
    .clk_i,
    .rst_ni,
    .inp_data_i  (bank_req_data),
    .inp_valid_i (bank_trans_req_valid),
    .inp_ready_o (bank_trans_req_ready),
    .oup_data_o  (trans_req_data_o),
    .oup_valid_o (trans_req_valid_o),
    .oup_ready_i (trans_req_ready_i)
);

//=========================================================================
// Translation response routing by `.bank`
//   Both banks see the same response payload (the existing controller
//   ignores the bank field); only the matching bank sees `valid`.
//   `trans_resp_ready_o` is the ready of that same bank.
//=========================================================================
always_comb begin : bank_resp_route
    bank_trans_resp_data[0] = trans_resp_data_i;
    bank_trans_resp_data[1] = trans_resp_data_i;
    bank_trans_resp_valid[0] = trans_resp_valid_i && (trans_resp_data_i.bank == 1'b0);
    bank_trans_resp_valid[1] = trans_resp_valid_i && (trans_resp_data_i.bank == 1'b1);
end

assign trans_resp_ready_o = trans_resp_data_i.bank ? bank_trans_resp_ready[1]
                                                   : bank_trans_resp_ready[0];

    // ensure coupled AW to avoid deadlocks
burst_req_o.opt.beo.decouple_aw    = '0;
burst_req_o.opt.beo.decouple_rw    = dma_reg2hw.conf.decouple.q;
    // this frontend currently only supports completely debursting
burst_req_o.opt.beo.src_max_llen   = '0;
    // this frontend currently only supports completely debursting
burst_req_o.opt.beo.dst_max_llen   = '0;
burst_req_o.opt.beo.src_reduce_len = dma_reg2hw.conf.deburst.q;
burst_req_o.opt.beo.dst_reduce_len = dma_reg2hw.conf.deburst.q;

    // serialization no longer supported
// burst_req_o.serialize   = dma_reg2hw.conf.serialize.q;

// calculate the page with in bits
always_comb begin : proc_read_addr_width
    // should the "virtual" page be reduced? e.g. the transfers split into
    // smaller chunks than the AXI page size?
    r_page_addr_width = OffsetWidth + (opt_tf_q.src_reduce_len ? opt_tf_q.src_max_llen : 'd8);
    // a page can be a maximum of 4kB (12 bit)
    r_page_addr_width = r_page_addr_width > PageAddrWidth ? PageAddrWidth : r_page_addr_width;
end
// calculate the page size in byte
assign r_page_size = (1 << r_page_addr_width);

// calculate the page with in bits
always_comb begin : proc_write_addr_width
    // should the "virtual" page be reduced? e.g. the transfers split into
    // smaller chunks than the AXI page size?
    w_page_addr_width = OffsetWidth + (opt_tf_q.dst_reduce_len ? opt_tf_q.dst_max_llen : 'd8);
    // a page can be a maximum of 4kB (12 bit)
    w_page_addr_width = w_page_addr_width > PageAddrWidth ? PageAddrWidth : w_page_addr_width;
end
// calculate the page size in byte
assign w_page_size = (1 << w_page_addr_width);
